int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int error = -EINVAL;

    skb = skb_peek(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (size > skb->len) {
        size = skb->len;
    }

    if (memcpy_to_msg(msg, skb->data, size) != 0) {
        return -EFAULT;
    }

    copied = size;

    if (flags & MSG_TRUNC) {
        msg->msg_flags |= MSG_TRUNC;
    }

    skb_unlink(skb, &sk->sk_receive_queue);
    skb_free(skb);

    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue)) {
        return 0;
    }

    if (sk->sk_flow_stop && !skb_queue_empty(&sk->sk_receive_queue)) {
        sk->sk_flow_stop = 0;
    }

    return copied;
}
